import sys

N = 16
CELLS = N * N
INF = 512

DIST = [[0] * CELLS for _ in range(CELLS)]
for a in range(CELLS):
    ar, ac = divmod(a, N)
    for b in range(CELLS):
        br, bc = divmod(b, N)
        DIST[a][b] = (ar - br) ** 2 + (ac - bc) ** 2


def read_turn():
    line = sys.stdin.readline()
    if not line:
        return None
    game_id, side, ply, my_score, opponent_score = line.split()
    game_id, ply, my_score, opponent_score = map(int, (game_id, ply, my_score, opponent_score))
    side = 1 if side == "B" else 2
    rows = [sys.stdin.readline().strip() for _ in range(N)]
    count = int(sys.stdin.readline())
    actions = [int(sys.stdin.readline()) for _ in range(count)]
    return side, ply, rows, actions


def choose(side, rows, actions):
    stones = [[], []]
    for row in range(N):
        for col in range(N):
            cell = rows[row][col]
            if cell == "B":
                stones[0].append(row * N + col)
            elif cell == "W":
                stones[1].append(row * N + col)

    own = side - 1
    other = 1 - own
    nearest = [[INF] * CELLS for _ in range(2)]
    for player in range(2):
        for stone in stones[player]:
            distances = DIST[stone]
            field = nearest[player]
            for cell in range(CELLS):
                if distances[cell] < field[cell]:
                    field[cell] = distances[cell]

    best_action = actions[0]
    best_value = -10**18
    for action in actions:
        influence = DIST[action]
        value = 0
        own_field = nearest[own]
        other_field = nearest[other]
        for cell in range(CELLS):
            own_distance = min(own_field[cell], influence[cell])
            value += other_field[cell] - own_distance
        if value > best_value:
            best_value = value
            best_action = action
    return best_action


while True:
    turn = read_turn()
    if turn is None:
        break
    side, _, rows, actions = turn
    print(choose(side, rows, actions), flush=True)

