from __future__ import annotations

import random
import sys
from dataclasses import dataclass
from typing import Callable, Optional, Sequence
BOARD_SIZE = 16


CELL_COUNT = BOARD_SIZE * BOARD_SIZE


EMPTY = 0


BLACK = 1


WHITE = -1


EPSILON = 1e-10


DEFAULT_INTERIOR_DIAGONAL_WEIGHT = 0.700000


DEFAULT_EDGE_DIAGONAL_WEIGHT = 0.754744


DEFAULT_CORNER_DIAGONAL_WEIGHT = 0.979201


DEFAULT_OPPONENT_REPLY_COEFFICIENT = 0.885498


DEFAULT_REPLY_TOP_K = 5


DEFAULT_REPLY_MAX_SHARE = 0.500000


def build_board_geometry() -> tuple[
    tuple[tuple[int, ...], ...],
    tuple[tuple[int, ...], ...],
    tuple[tuple[int, ...], ...],
    tuple[tuple[int, ...], ...],
    tuple[tuple[int, ...], ...],
    tuple[tuple[int, ...], ...],
]:
    radius_one: list[tuple[int, ...]] = []
    radius_two: list[tuple[int, ...]] = []
    orthogonal_targets: list[tuple[int, ...]] = []
    diagonal_targets: list[tuple[int, ...]] = []
    tactical_windows: list[tuple[int, ...]] = []
    local_windows: list[tuple[int, ...]] = []

    sentinel = CELL_COUNT

    for center in range(CELL_COUNT):
        row, col = divmod(center, BOARD_SIZE)

        one = tuple(
            nearby_row * BOARD_SIZE + nearby_col
            for nearby_row in range(max(0, row - 1), min(BOARD_SIZE, row + 2))
            for nearby_col in range(max(0, col - 1), min(BOARD_SIZE, col + 2))
        )
        two = tuple(
            nearby_row * BOARD_SIZE + nearby_col
            for nearby_row in range(max(0, row - 2), min(BOARD_SIZE, row + 3))
            for nearby_col in range(max(0, col - 2), min(BOARD_SIZE, col + 3))
        )
        orthogonal = tuple(
            target
            for target in one
            if divmod(target, BOARD_SIZE)[0] == row
            or divmod(target, BOARD_SIZE)[1] == col
        )
        diagonal = tuple(target for target in one if target not in orthogonal)

        # 对手回复收益最多受候选点半径 2 内回复影响；这些回复自身的
        # 九宫格又最多依赖候选点半径 4 内棋子。因此用 9×9 棋形签名
        # 合并完全等价的候选情况，边界以 sentinel 编码。
        tactical_window: list[int] = []
        for row_offset in range(-4, 5):
            for col_offset in range(-4, 5):
                scan_row = row + row_offset
                scan_col = col + col_offset
                if 0 <= scan_row < BOARD_SIZE and 0 <= scan_col < BOARD_SIZE:
                    tactical_window.append(scan_row * BOARD_SIZE + scan_col)
                else:
                    tactical_window.append(sentinel)

        radius_one.append(one)
        radius_two.append(two)
        orthogonal_targets.append(orthogonal)
        diagonal_targets.append(diagonal)
        tactical_windows.append(tuple(tactical_window))
        local_windows.append(one)

    return (
        tuple(radius_one),
        tuple(radius_two),
        tuple(orthogonal_targets),
        tuple(diagonal_targets),
        tuple(tactical_windows),
        tuple(local_windows),
    )


(
    RADIUS_ONE,
    RADIUS_TWO,
    ORTHOGONAL_TARGETS,
    DIAGONAL_TARGETS,
    TACTICAL_WINDOWS,
    LOCAL_WINDOWS,
) = build_board_geometry()


RADIUS_ONE_SETS = tuple(frozenset(items) for items in RADIUS_ONE)


RADIUS_TWO_SETS = tuple(frozenset(items) for items in RADIUS_TWO)


@dataclass(frozen=True)
class AIParameters:
    interior_diagonal: float = DEFAULT_INTERIOR_DIAGONAL_WEIGHT
    edge_diagonal: float = DEFAULT_EDGE_DIAGONAL_WEIGHT
    corner_diagonal: float = DEFAULT_CORNER_DIAGONAL_WEIGHT
    opponent_reply_coefficient: float = DEFAULT_OPPONENT_REPLY_COEFFICIENT
    reply_top_k: int = DEFAULT_REPLY_TOP_K
    reply_max_share: float = DEFAULT_REPLY_MAX_SHARE

    def validated(self) -> "AIParameters":
        interior = max(0.0, min(1.0, float(self.interior_diagonal)))
        edge = max(interior, min(1.0, float(self.edge_diagonal)))
        corner = max(edge, min(1.0, float(self.corner_diagonal)))
        coefficient = max(0.0, float(self.opponent_reply_coefficient))
        top_k = max(1, int(self.reply_top_k))
        max_share = max(0.0, min(1.0, float(self.reply_max_share)))
        return AIParameters(
            interior_diagonal=interior,
            edge_diagonal=edge,
            corner_diagonal=corner,
            opponent_reply_coefficient=coefficient,
            reply_top_k=top_k,
            reply_max_share=max_share,
        )

    def short_text(self) -> str:
        fixed = self.validated()
        return (
            f"内部 {fixed.interior_diagonal:.6f}　"
            f"边缘 {fixed.edge_diagonal:.6f}　"
            f"角点 {fixed.corner_diagonal:.6f}　"
            f"λ {fixed.opponent_reply_coefficient:.6f}"
        )


class GameState:
    """棋盘状态：仅增量维护棋子和八邻域禁入计数。"""

    def __init__(self) -> None:
        self.cells: list[int] = [EMPTY] * CELL_COUNT
        self.blocked: list[int] = [0] * CELL_COUNT

    @staticmethod
    def color_index(color: int) -> int:
        return 0 if color == BLACK else 1

    @staticmethod
    def index(row: int, col: int) -> int:
        return row * BOARD_SIZE + col

    @staticmethod
    def coordinate(index: int) -> tuple[int, int]:
        return divmod(index, BOARD_SIZE)

    def clone(self) -> "GameState":
        copied = GameState()
        copied.cells = self.cells.copy()
        copied.blocked = self.blocked.copy()
        return copied

    def is_legal(self, move: int) -> bool:
        return (
            0 <= move < CELL_COUNT
            and self.cells[move] == EMPTY
            and self.blocked[move] == 0
        )

    def legal_moves(self) -> list[int]:
        return [
            move
            for move in range(CELL_COUNT)
            if self.cells[move] == EMPTY and self.blocked[move] == 0
        ]

    def place(self, move: int, color: int) -> None:
        if color not in (BLACK, WHITE):
            raise ValueError("棋子颜色无效。")
        if not self.is_legal(move):
            raise ValueError(f"非法落子：{self.coordinate(move)}")

        self.cells[move] = color
        for target in RADIUS_ONE[move]:
            self.blocked[target] += 1

    def undo(self, move: int) -> None:
        if self.cells[move] == EMPTY:
            raise ValueError(f"无法撤销空位置：{self.coordinate(move)}")

        for target in RADIUS_ONE[move]:
            self.blocked[target] -= 1
            if self.blocked[target] < 0:
                raise RuntimeError("禁入计数出现负数。")
        self.cells[move] = EMPTY


@dataclass(frozen=True)
class MoveEvaluation:
    move: int
    total_score: float
    immediate_gain: float
    reply_threat: float
    tied_best_moves: int


ProgressCallback = Callable[[int, int, str], None]


class LookaheadComputer:
    """
    旧模型冠军的完整落子评价：

        最终评价 = 本步即时收益 - λ × 对手回复威胁

    局部格点控制采用旧模型：目标格九宫格内所有棋子贡献线性相加，
    正交/中心贡献为 1，斜角贡献为目标位置对应权重，最后截断到 [-1, 1]。

    对手回复威胁：

        max_share × 最高回复收益
        + (1 - max_share) × 前 top_k 强回复收益平均值
    """

    def __init__(self, parameters: AIParameters) -> None:
        self.parameters = parameters.validated()
        self.diagonal_weights = tuple(
            self.diagonal_weight(*divmod(target, BOARD_SIZE))
            for target in range(CELL_COUNT)
        )

    def diagonal_weight(self, target_row: int, target_col: int) -> float:
        on_horizontal_edge = target_row in (0, BOARD_SIZE - 1)
        on_vertical_edge = target_col in (0, BOARD_SIZE - 1)

        if on_horizontal_edge and on_vertical_edge:
            return self.parameters.corner_diagonal
        if on_horizontal_edge or on_vertical_edge:
            return self.parameters.edge_diagonal
        return self.parameters.interior_diagonal

    def value_of_cell(
        self,
        state: GameState,
        target: int,
        perspective: int,
        added_move: Optional[int] = None,
        added_color: int = EMPTY,
    ) -> float:
        """旧模型的单格评价，可选虚拟加入一枚棋子而不修改状态。"""
        occupant = (
            added_color
            if added_move is not None and target == added_move
            else state.cells[target]
        )
        if occupant != EMPTY:
            return 1.0 if occupant == perspective else -1.0

        target_row, target_col = divmod(target, BOARD_SIZE)
        diagonal_weight = self.diagonal_weights[target]
        value = 0.0

        for source in RADIUS_ONE[target]:
            piece = (
                added_color
                if added_move is not None and source == added_move
                else state.cells[source]
            )
            if piece == EMPTY:
                continue

            source_row, source_col = divmod(source, BOARD_SIZE)
            if abs(source_row - target_row) == 1 and abs(source_col - target_col) == 1:
                weight = diagonal_weight
            else:
                weight = 1.0

            value += (1.0 if piece == perspective else -1.0) * weight

        return max(-1.0, min(1.0, value))

    def move_gain(self, state: GameState, move: int, color: int) -> float:
        gain = 0.0
        for target in RADIUS_ONE[move]:
            before = self.value_of_cell(state, target, color)
            after = self.value_of_cell(
                state,
                target,
                color,
                added_move=move,
                added_color=color,
            )
            gain += after - before
        return gain

    @staticmethod
    def tactical_signature(state: GameState, move: int, color: int) -> bytes:
        encoded = bytearray()
        sentinel = CELL_COUNT

        for index in TACTICAL_WINDOWS[move]:
            if index == sentinel:
                encoded.append(3)
            else:
                encoded.append(state.cells[index] * color + 1)

        return bytes(encoded)

    @staticmethod
    def add_gain_count(
        gain_counts: dict[float, int],
        gain: float,
        count: int = 1,
    ) -> None:
        key = round(float(gain), 12)
        gain_counts[key] = gain_counts.get(key, 0) + count

    def aggregate_reply_threat(self, gain_counts: dict[float, int]) -> float:
        if not gain_counts:
            return 0.0

        remaining = self.parameters.reply_top_k
        top_sum = 0.0
        top_count = 0
        highest: Optional[float] = None

        for gain in sorted(gain_counts, reverse=True):
            count = gain_counts[gain]
            if count <= 0:
                continue
            if highest is None:
                highest = gain

            used = min(remaining, count)
            top_sum += gain * used
            top_count += used
            remaining -= used
            if remaining == 0:
                break

        if highest is None or top_count == 0:
            return 0.0

        top_mean = top_sum / top_count
        max_share = self.parameters.reply_max_share
        return max_share * highest + (1.0 - max_share) * top_mean

    def reply_threat_after_move(
        self,
        state: GameState,
        move: int,
        color: int,
        legal_set: set[int],
        baseline_opponent_gains: dict[int, float],
        baseline_sorted_replies: Sequence[int],
    ) -> float:
        opponent = -color
        changed_set = RADIUS_TWO_SETS[move]
        blocked_set = RADIUS_ONE_SETS[move]

        state.place(move, color)
        try:
            gain_counts: dict[float, int] = {}
            collected_unaffected = 0

            for reply in baseline_sorted_replies:
                if reply in changed_set:
                    continue
                self.add_gain_count(gain_counts, baseline_opponent_gains[reply])
                collected_unaffected += 1
                if collected_unaffected >= self.parameters.reply_top_k:
                    break

            for reply in RADIUS_TWO[move]:
                if reply not in legal_set or reply in blocked_set:
                    continue
                self.add_gain_count(
                    gain_counts,
                    self.move_gain(state, reply, opponent),
                )

            return self.aggregate_reply_threat(gain_counts)
        finally:
            state.undo(move)

    def choose_move(
        self,
        state: GameState,
        color: int,
        rng: random.Random,
        progress_callback: Optional[ProgressCallback] = None,
    ) -> Optional[MoveEvaluation]:
        legal_moves = state.legal_moves()
        if not legal_moves:
            return None

        coefficient = self.parameters.opponent_reply_coefficient
        phase_count = 1 if coefficient <= EPSILON else 3
        total_steps = len(legal_moves) * phase_count
        completed = 0

        def report(stage: str) -> None:
            if progress_callback is not None:
                progress_callback(completed, total_steps, stage)

        immediate_gains: dict[int, float] = {}
        for move in legal_moves:
            immediate_gains[move] = self.move_gain(state, move, color)
            completed += 1
            report("计算本步即时收益")

        if coefficient <= EPSILON:
            best_score = max(immediate_gains.values())
            best_moves = [
                move
                for move, score in immediate_gains.items()
                if abs(score - best_score) <= EPSILON
            ]
            chosen_move = rng.choice(best_moves)
            return MoveEvaluation(
                move=chosen_move,
                total_score=best_score,
                immediate_gain=best_score,
                reply_threat=0.0,
                tied_best_moves=len(best_moves),
            )

        legal_set = set(legal_moves)
        opponent = -color
        baseline_opponent_gains: dict[int, float] = {}
        for move in legal_moves:
            baseline_opponent_gains[move] = self.move_gain(state, move, opponent)
            completed += 1
            report("缓存对手当前点位收益")

        baseline_sorted_replies = sorted(
            legal_moves,
            key=baseline_opponent_gains.__getitem__,
            reverse=True,
        )

        threat_by_signature: dict[bytes, float] = {}
        evaluations: dict[int, tuple[float, float]] = {}
        best_score = float("-inf")
        best_moves: list[int] = []

        for move in legal_moves:
            signature = self.tactical_signature(state, move, color)
            if signature in threat_by_signature:
                reply_threat = threat_by_signature[signature]
            else:
                reply_threat = self.reply_threat_after_move(
                    state,
                    move,
                    color,
                    legal_set,
                    baseline_opponent_gains,
                    baseline_sorted_replies,
                )
                threat_by_signature[signature] = reply_threat

            total_score = immediate_gains[move] - coefficient * reply_threat
            evaluations[move] = (total_score, reply_threat)

            if total_score > best_score + EPSILON:
                best_score = total_score
                best_moves = [move]
            elif abs(total_score - best_score) <= EPSILON:
                best_moves.append(move)

            completed += 1
            report("枚举对手下一步并合并等价情况")

        chosen_move = rng.choice(best_moves)
        total_score, reply_threat = evaluations[chosen_move]
        return MoveEvaluation(
            move=chosen_move,
            total_score=total_score,
            immediate_gain=immediate_gains[chosen_move],
            reply_threat=reply_threat,
            tied_best_moves=len(best_moves),
        )


class CachedState(GameState):
    # Cache the same unclipped local linear influence used by the original evaluator.
    def __init__(self, diagonal_weights):
        super().__init__()
        self.control = [0.0] * CELL_COUNT
        self.diagonal_weights = diagonal_weights

    def change_control(self, move, color):
        row, col = divmod(move, BOARD_SIZE)
        for target in RADIUS_ONE[move]:
            tr, tc = divmod(target, BOARD_SIZE)
            weight = self.diagonal_weights[target] if tr != row and tc != col else 1.0
            self.control[target] += color * weight

    def place(self, move, color):
        super().place(move, color)
        self.change_control(move, color)

    def undo(self, move):
        color = self.cells[move]
        super().undo(move)
        self.change_control(move, -color)


class CachedComputer(LookaheadComputer):
    # Only the repeated cell-value calculation changes; scoring and tie choices are inherited.
    def value_of_cell(self, state, target, perspective, added_move=None, added_color=EMPTY):
        occupant = added_color if added_move is not None and target == added_move else state.cells[target]
        if occupant != EMPTY:
            return 1.0 if occupant == perspective else -1.0
        value = state.control[target]
        if added_move is not None:
            tr, tc = divmod(target, BOARD_SIZE)
            mr, mc = divmod(added_move, BOARD_SIZE)
            if abs(tr - mr) <= 1 and abs(tc - mc) <= 1:
                weight = self.diagonal_weights[target] if tr != mr and tc != mc else 1.0
                value += added_color * weight
        return max(-1.0, min(1.0, perspective * value))


def read_turn():
    line = sys.stdin.readline()
    if not line:
        return None
    game_id, side, ply, my_score, opponent_score = line.split()
    game_id, ply, my_score, opponent_score = map(int, (game_id, ply, my_score, opponent_score))
    side = 1 if side == "B" else 2
    rows = [sys.stdin.readline().strip() for _ in range(BOARD_SIZE)]
    count = int(sys.stdin.readline())
    actions = [int(sys.stdin.readline()) for _ in range(count)]
    return side, rows, actions


def main():
    computer = CachedComputer(AIParameters())
    rng = random.Random(0x48455841)
    while True:
        turn = read_turn()
        if turn is None:
            return
        side, rows, actions = turn
        state = CachedState(computer.diagonal_weights)
        for row, text in enumerate(rows):
            for column, piece in enumerate(text):
                if piece in ("B", "W"):
                    state.place(row * BOARD_SIZE + column, BLACK if piece == "B" else WHITE)
        result = computer.choose_move(state, BLACK if side == 1 else WHITE, rng)
        if result is None or result.move not in actions:
            raise RuntimeError("Champion and referee legal actions disagree")
        print(result.move, flush=True)


if __name__ == "__main__":
    main()
